<script lang="ts">
 import {createEventDispatcher} from 'svelte';
 import type {Draft,Workflow,TestReceipt} from './automations-client';
 import './automations.css';
 export let draft:Draft|null=null;export let workflow:Workflow|null=null;export let test:TestReceipt|null=null;export let busy=false;export let engineAvailable=false;
 const dispatch=createEventDispatcher<{test:Draft;activate:Draft;pause:Workflow;resume:Workflow;edit:Draft|Workflow;history:Workflow}>();
 const checkLabel=(id:string)=>(({connections:'Company connections',permissions:'Required permissions',trigger:'Trigger readiness',parameters:'Required details',approval:'Human approval',engine:'Execution readiness',orders_create_access:'Shopify new-order event access'} as Record<string,string>)[id]||'Readiness check');
 const checkReason=(reason:string)=>(({SHOPIFY_PUBLIC_APP_REVIEW_REQUIRED:'Shopify must approve order access for this app before new-order notifications can be enabled.',SHOPIFY_WEBHOOK_ACCESS_OR_REVIEW_REQUIRED:'Shopify has not approved this app’s access to new-order events yet.',SHOPIFY_WEBHOOK_ACCESS_UNAVAILABLE:'New-order event access could not be checked. Reconnect Shopify and test again.',SHOPIFY_WEBHOOK_ACCESS_REQUIRED:'This Shopify account does not currently allow the required order event subscription.',SHOPIFY_ORDER_NOTIFICATIONS_UNAVAILABLE:'New-order notifications are not enabled on this deployment.',REVIEWED_CONNECTOR_UNAVAILABLE:'This business integration is not ready for execution.',TRIGGER_NOT_CONFIGURED:'This request source is not connected to verified incoming events yet.',REQUESTING_NATIVE_BOT_REQUIRED:'Choose the requesting bot in the original conversation.',PROVIDER_SCOPES_REQUIRED:'Reconnect the business app with the requested permissions.',CONNECTION_REQUIRED:'Connect the required business app.',REAUTH_REQUIRED:'Reconnect the expired business account.',PROVIDER_ACCOUNT_CHANGED:'The provider account changed. Review its connection.',CONNECTION_CHANGED:'The company connection changed. Refresh and test again.',PROVIDER_IDENTITY_VERIFIER_UNAVAILABLE:'Account verification is not available yet.',connection_required:'Connect the required business app.',missing_connection:'Connect the required business app.',engine_unavailable:'Execution is not available on this deployment.',missing_fields:'Complete the remaining setup questions.',approval_required:'An assigned approver is required.'} as Record<string,string>)[reason]||'This check needs attention before activation.');
 let confirming=false,resumeConfirm=false,seen='';
 $: item=workflow||draft;
 $: if(item&&seen!==item.id+':'+item.revision){seen=item.id+':'+item.revision;confirming=false;resumeConfirm=false;}
 $: tested=!!draft&&test?.draftId===draft.id&&test.revision===draft.revision&&test.status==='PASSED'&&test.sideEffects===false;
 $: canActivate=!!draft&&draft.actions.canActivate&&!draft.missing.length&&tested&&engineAvailable;
</script>
{#if item}<section class="starli-automations review-card" aria-label="Automation review"><div class="sa-heading"><div><span class="sa-eyebrow">WORKFLOW REVIEW</span><h3>{item.name}</h3></div><span class="sa-badge">{item.status.replaceAll('_',' ').toLowerCase()}</span></div><div class="sa-flow"><div><span class="sa-step-dot">1</span><div><small>WHEN</small><strong>{item.summary.trigger}</strong></div></div>{#each item.summary.actions as action,index}<div><span class="sa-step-dot">{index+2}</span><div><small>THEN</small><strong>{action}</strong></div></div>{/each}</div><div class="sa-note"><strong>{item.summary.approvalRequired?'Human approval required':'One-time activation'}</strong><p class="sa-muted">{item.intent==='shopify_new_order_chat'?'After activation, verified new-order notifications are posted to this original Starli conversation. Informational notifications do not need another approval.':item.intent==='internal_approval_test'?'Each internal test run asks its assigned approver before recording a test receipt.':item.intent==='shopify_order_slack_review'?'Each Slack message requires its assigned approver to review the exact order, workspace, channel and content.':'Each consequential request is reviewed separately with its exact resource and amount. Activating this automation does not approve its future actions.'}</p></div>
 {#if workflow?.intent==='shopify_new_order_chat'&&workflow.triggerStatus}<dl class="sa-details"><div><dt>Shopify store</dt><dd>{workflow.triggerStatus.shopDomain||'Not subscribed'}</dd></div><div><dt>New-order event status</dt><dd>{workflow.status==='ACTIVE'&&workflow.triggerStatus.status==='ACTIVE'?'Listening for new Shopify orders':workflow.status==='PAUSED'||workflow.triggerStatus.status==='PAUSED'?'Notifications paused':workflow.triggerStatus.status==='PROVISIONING'?'Connection being activated':workflow.triggerStatus.status==='NOT_SUBSCRIBED'?'Not subscribed':'Needs attention'}</dd></div><div><dt>Notification destination</dt><dd>This original Starli conversation</dd></div></dl>{/if}
 {#if test&&draft&&test.draftId===draft.id&&test.revision===draft.revision}<div class="sa-test" role="status"><strong>{test.status==='PASSED'?'Non-destructive checks passed':'Test blocked'}</strong><p class="sa-muted">No external actions were performed.</p>{#each test.checks as check}<div><span>{checkLabel(check.id)}</span><span>{check.status.toLowerCase()}{check.reason?' · '+checkReason(check.reason):''}</span></div>{/each}</div>{/if}
 {#if !engineAvailable}<p class="sa-warning">Execution is not available on this deployment. Drafts can be reviewed; activation remains unavailable.</p>{/if}
 {#if confirming&&draft}<div class="sa-confirm"><strong>Activate this automation?</strong><p class="sa-muted">{draft.intent==='shopify_new_order_chat'?'Enable new Shopify order notifications in this original Starli conversation. Each informational notification will arrive here without another approval.':draft.intent==='internal_approval_test'?'Enable this internal approval check. Each run still requires its assigned human approval; no external business action is authorized.':'Enable the reviewed workflow for its configured trigger. Separate per-action approvals still apply.'}</p><div class="sa-actions"><button disabled={busy} on:click={()=>confirming=false}>Keep as draft</button><button class="sa-primary" disabled={busy||!canActivate} on:click={()=>draft&&dispatch('activate',draft)}>Authorize activation</button></div></div>{:else}<div class="sa-actions">{#if draft}<button disabled={busy||!draft.actions.canTest} on:click={()=>draft&&dispatch('test',draft)}>{busy?'Working…':'Test automation'}</button><button class="sa-primary" disabled={busy||!canActivate} on:click={()=>confirming=true}>Activate</button>{/if}{#if workflow}<button disabled={busy||!workflow.actions.canPause} on:click={()=>workflow&&dispatch('pause',workflow)}>Pause</button>{#if workflow.actions.canResume}<button class="sa-primary" disabled={busy} on:click={()=>resumeConfirm=true}>Resume</button>{/if}<button disabled={busy} on:click={()=>workflow&&dispatch('history',workflow)}>View history</button>{/if}<button disabled={busy||!item.actions.canManage} on:click={()=>item&&dispatch('edit',item)}>Edit</button></div>{/if}
 {#if resumeConfirm&&workflow}<div class="sa-confirm"><strong>{workflow.intent==='shopify_new_order_chat'?'Resume new-order notifications?':'Resume this automation?'}</strong><p class="sa-muted">Resume the reviewed workflow in its original conversation after the server rechecks its current connection and readiness.</p><div class="sa-actions"><button disabled={busy} on:click={()=>resumeConfirm=false}>Keep paused</button><button class="sa-primary" disabled={busy||!workflow.actions.canResume} on:click={()=>workflow&&dispatch('resume',workflow)}>Authorize resume</button></div></div>{/if}
 <small class="sa-reference">{workflow?'Workflow':'Draft'} {item.id} · revision {item.revision}</small></section>{/if}
